/*
    0. 参考文章：https://bbs.yangzihome.space/archives/blast-ocr
    1. OCR识别代码：https://github.com/yangzifun/codeocr
*/


beforeRequest = func(req) {
    // 1. 发送验证码获取请求
    captcha_req_packet = `GET /get_and_solve?template=get.txt HTTP/1.1
Host: 127.0.0.1:8888
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/83.0.4103.116 Safari/537.36
Connection: close

`
    // 发送HTTP请求
    captcha_rsp_str, _, err = poc.HTTP(captcha_req_packet, poc.https(false))
    if err != nil {
        log.info("获取验证码请求失败: %v", err)
        return req
    }

    // 2. 从响应中提取 key 和 result 的值
    // 使用单行正则表达式字符串
    key_matches = re2.FindSubmatch(captcha_rsp_str, `"key"\s*:\s*"([^"]+)"`)
    result_matches = re2.FindSubmatch(captcha_rsp_str, `"result"\s*:\s*"([^"]+)"`)
    
    // 初始化变量
    key_val := ""
    result_val := ""

    // 安全提取捕获组内容
    if len(key_matches) >= 2 {
        key_val = key_matches[1]
    }
    if len(result_matches) >= 2 {
        result_val = result_matches[1]
    }

    // 验证提取结果
    if key_val == "" || result_val == "" {
        log.info("提取验证码失败，响应内容: %s", captcha_rsp_str)
        return req
    }
    
    log.info("成功获取验证码 => Key: %s, Result: %s", key_val, result_val)

    // 3. 替换主请求中的占位符
    req = re.ReplaceAll(req, `_key_`, key_val)
    req = re.ReplaceAll(req, `_result_`, result_val)

    // 4. 返回修改后的请求
    return []byte(req)
}
